def solution(input_str):
    """
    Finds the lexicographically smallest word >= s that satisfies all vowel/consonant rules.
    """
    input_lines = input_str.strip().split('\n')

    # Parse vowels/consonants
    vc_type = input_lines[0]
    l = len(vc_type)
    vowel_set = set()
    for i, v in enumerate(vc_type):
        if v == 'V':
            vowel_set.add(chr(ord('a') + i))

    # Parse n, m
    nm_line = input_lines[1].split()
    n = int(nm_line[0])
    m = int(nm_line[1])

    # Parse rules
    rules = []
    for i in range(2, 2 + m):
        parts = input_lines[i].split()
        pos1, pos2 = int(parts[0]), int(parts[2])
        t1, t2 = parts[1], parts[3]
        rules.append((pos1, t1, pos2, t2))

    s = input_lines[2 + m]

    # Determine optimal character for position
    prefers_vowel = ["a", "e", "i", "o", "u"]
    prefers_consonant = ["b", "c", "d", "f", "g", "h", "j", "k", "l", "m"]

    # Backtracking with constraint checking
    def check_valid(types):
        for pos1, t1, pos2, t2 in rules:
            if types[pos1] is not None:
                if types[pos1] != t1:
                    continue
                if types[pos2] is not None:
                    if types[pos2] != t2:
                        return False
                # No violation if pos2 not assigned yet; will be checked later
        return True

    def backtrack(pos, current_types):
        if pos == n:
            return True

        # Try characters from s[pos] (to be minimal >= s)
        start_char = s[pos] if pos < len(s) else chr(ord('a') + 0)

        # But we also must respect s[pos] as minimum allowed
        if pos >= len(s):
            start_char = 'a'

        for char_code in range(ord(start_char), ord('a') + l):
            c = chr(char_code)
            ctype = 'V' if c in vowel_set else 'C'
            current_types[pos] = ctype

            # Check consistency with already assigned chars
            valid_now = True
            for r in rules:
                rp1, r1t, rp2, r2t = r
                if rp1 == pos and current_types[rp1] is not None and current_types[pos] == r1t:
                    if rp1 < pos:
                        # This rule should have been checked before, continue
                        continue
                    if rp2 < pos and current_types[rp2] is not None:
                        if current_types[rp2] != r2t:
                            valid_now = False
                            break

                if rp2 == pos and current_types[pos] is not None and current_types[pos] == r2t:
                    if rp1 < pos and current_types[rp1] is not None:
                        pass
                    # Check if forward constraints can still be satisfied
                    if rp1 >= pos and current_types[rp1] is not None and current_types[rp1] != r1t:
                        valid_now = False
                        break

            if valid_now:
                # Check all implications for constraints already placed
                if check_valid(current_types):
                    if backtrack(pos + 1, current_types):
                        return True

            current_types[pos] = None

        return False

    result_chars = []
    for _ in range(n):
        result_chars.append(None)

    def try_fill(pos, from_s):
        if pos == n:
            return True

        min_char_idx = ord(s[pos]) - ord('a') if from_s else 0
        max_char_idx = min(ord(s[pos]) + (l - 1), ord('a') + l - 1)  # Adjusted

        for i in range(min_char_idx, l):
            c = chr(ord('a') + i)
            c_type = 'V' if c in vowel_set else 'C'

            # Check if placement valid given current state and rules
            valid = True
            temp_types = current_types.copy()
            temp_types[pos] = c_type

            # Verify all rules satisfied
            for r in rules:
                rp1, r1t, rp2, r2t = r
                if rp1 == pos:
                    if temp_types[rp1] is not None and temp_types[rp1] != r1t:
                        valid = False
                        break
                    if rp2 < pos and temp_types[rp2] is not None and temp_types[rp2] != r2t:
                        valid = False
                        break
                if r2t == c_type and rp1 == pos:
                    continue
                if rp2 == pos:
                    if temp_types[rp2] != c_type:
                        valid = False
                        break

            if valid:
                if try_fill(pos + 1, False):
                    result_chars[pos] = c
                    return True

        result_chars[pos] = None
        return False

    if try_fill(0, True):
        return ''.join(result_chars)
    return "-1"

