from collections import deque, defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list (handle duplicate edges and self-loops)
    adj = defaultdict(list)
    for i in range(1, m + 1):
        parts = lines[i].split()
        u, v = int(parts[0]), int(parts[1])
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components using BFS
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = deque([i])
            visited[i] = True
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    # Generate lucky numbers
    def is_lucky(num):
        for d in str(num):
            if d not in ('4', '7'):
                return False
        return True

    lucky_numbers = []
    for i in range(1, n + 1):
        if is_lucky(i):
            lucky_numbers.append(i)

    # Check if any component is already lucky
    for size in component_sizes:
        if size in lucky_numbers:
            return "0\n"

    # Sort component sizes in descending order for better greedy selection
    component_sizes.sort(reverse=True)

    # Use BFS/DP to find minimum components to reach each lucky sum
    # dp[s] = (components_used, possible) cache
    min_components = {}

    # Base case: each component individually
    for size in component_sizes:
        min_components[size] = min_components.get(size, float('inf'))
        min_components[size] = min(min_components.get(size, float('inf')), 1)

    # Try to build up to each lucky number
    for target in lucky_numbers:
        if target == 0:
            continue

        # BFS to find minimum components for this target
        if target in min_components:
            continue
        min_components[target] = float('inf')

    # BFS for shortest path to each lucky number
    from collections import deque as dq

    queue = dq()
    queue.append((0, 0))  # (current_sum, num_components)

    best = {}
    best[0] = 0

    while queue:
        current_sum, cnt = queue.popleft()

        if current_sum == target:
            if cnt < best.get(target, float('inf')):
                best[target] = cnt
                continue

        if current_sum > target:
            continue

        # Try adding each component
        for size in component_sizes:
            new_sum = current_sum
            if new_sum > target:
                break  # components are sorted, can break

            new_cnt = cnt + 1
            if new_sum in best:
                continue  # already found better path

            best[new_sum] = new_cnt
            queue.append((new_sum, new_cnt))

    # Find result among all lucky numbers
    result = float('inf')
    for lucky in lucky_numbers:
        if lucky in best:
            result = min(result, best[lucky])

    if result == float('inf'):
        return "-1\n"

    # Roads needed = components - 1
    return str(result - 1) + "\n"

