import math
from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    pairs = []
    for k in range(m):
        ik, jk = map(int, lines[2 + k].split())
        pairs.append((ik - 1, jk - 1))  # Convert to 0-indexed

    def prime_factors(x):
        factors = {}
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors[d] = factors.get(d, 0) + 1
                x //= d
            d += 1
        if x > 1:
            factors[x] = 1
        return factors

    position_factors = {}
    all_primes = set()

    for i in range(n):
        factors = prime_factors(a[i])
        position_factors[i] = factors
        all_primes.update(factors.keys())

    # Odd positions: i+1 is odd
    odd_indices = [i for i in range(n) if (i + 1) % 2 == 1]
    # Even positions: i+1 is even
    even_indices = [i for i in range(n) if (i + 1) % 2 == 0]

    class MaxFlow:
        def __init__(self, n_nodes):
            self.capacity = {}
            self.adj = [[] for _ in range(n_nodes)]

        def add_edge(self, u, v, cap):
            if (u, v) not in self.capacity:
                self.adj[u].append(len(self.adj[v]))
                self.adj[v].append(len(self.adj[u]) - 1)
            self.capacity[(u, v)] = self.capacity.get((u, v), 0) + cap
            self.capacity[(v, u)] = self.capacity.get((v, u), 0)

        def bfs(self, s, t, level):
            for i in range(len(level)):
                level[i] = -1
            level[s] = 0
            q = [s]
            while q:
                u = q.pop(0)
                for v, rev in self.adj[u]:
                    if self.capacity[(u, v)] > 0 and level[v] < 0:
                        level[v] = level[u] + 1
                        q.append(v)
            return level[t] >= 0

        def dfs(self, u, t, flow, ptr, level):
            if flow == 0 or u == t:
                return flow
            for i in range(ptr[u], len(self.adj[u])):
                ptr[u] = i
                v, rev = self.adj[u][i]
                if level[v] != level[u] + 1 or self.capacity[(u, v)] == 0:
                    continue
                pushed = self.dfs(v, t, min(flow, self.capacity[(u, v)]), ptr, level)
                if pushed > 0:
                    self.capacity[(u, v)] -= pushed
                    self.capacity[(v, u)] += pushed
                    return pushed
            return 0

        def max_flow(self, s, t):
            flow = 0
            while True:
                level = [0] * len(self.adj)
                if not self.bfs(s, t, level):
                    break
                ptr = [0] * len(self.adj)
                while True:
                    pushed = self.dfs(s, t, float('inf'), ptr, level)
                    if pushed == 0:
                        break
                    flow += pushed
            return flow

    total_ops = 0

    for prime in all_primes:
        num_odd = len(odd_indices)
        num_even = len(even_indices)
        n_nodes = 2 + num_odd + num_even

        flow = MaxFlow(n_nodes)
        source = 0
        sink = 1
        odd_start = 2
        even_start = 2 + num_odd

        # Source to odd positions
        for i, odd_idx in enumerate(odd_indices):
            cnt = position_factors[odd_idx].get(prime, 0)
            flow.add_edge(source, odd_start + i, cnt)

        # Even positions to sink
        for i, even_idx in enumerate(even_indices):
            cnt = position_factors[even_idx].get(prime, 0)
            flow.add_edge(even_start + i, sink, cnt)

        # Edges for good pairs (connecting odd to even positions)
        for ik, jk in pairs:
            # Adjust to 1-based for parity check
            ik1 = ik + 1
            jk1 = jk + 1

            # Check if ik is odd-indexed and jk is even-indexed
            if ik in odd_indices and jk in even_indices:
                oi = odd_indices.index(ik)
                ej = even_indices.index(jk)
                flow.add_edge(odd_start + oi, even_start + ej, float('inf'))

        total_ops += flow.max_flow(source, sink)

    return f"{total_ops}"

