def solution(input_str):
    # Re-write the classic solution for the bamboo problem
    # Parse input
    parts = input_str.replace('\n', ' ').split()

    n = int(parts[0])
    m = int(parts[1])
    k = int(parts[2])
    p = int(parts[3])

    h = []
    a = []
    idx = 4
    for _ in range(n):
        h_i = int(parts[idx])
        a_i = int(parts[idx + 1])
        h.append(h_i)
        a.append(a_i)
        idx += 2

    # Calculate maximum height if no hammers are used
    max_final_without_hammers = max(h[i] + a[i] * m for i in range(n))

    # If power is 0, hammers don't help
    if p == 0:
        return str(max_final_without_hammers)

    # Binary search on answer
    low, high = 0, max_final_without_hammers
    result = high

    while low <= high:
        mid = (low + high) // 2

        # Check if it's possible to have all bamboos at most at height mid
        total_strikes_needed = 0
        for i in range(n):
            final_h_no_strikes = h[i] + a[i] * m
            if final_h_no_strikes > mid:
                strikes_needed = (final_h_no_strikes - mid + p - 1) // p
                total_strikes_needed += strikes_needed

        available_strikes = k * m

        if total_strikes_needed <= available_strikes:
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(result)

def solution(input_str):
