    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())

    if n == 1:
        return "1\n"

    constraints = []
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if line:
            constraints.append(tuple(map(int, line.split())))

    if not constraints:
        return f"{n + 1}\n"

    MOD = 1000000007

    # Check all-love configuration: all constraints must be ci=1 (love)
    all_love_valid = True
    for u, v, ci in constraints:
        if ci == 0:
            all_love_valid = False
            break

    count = 1 if all_love_valid else 0

    # Find candidate center for star configurations
    # From love constraints, identify the common center
    love_constraints = [(u, v) for u, v, ci in constraints if ci == 1]

    if love_constraints:
        # All love constraints must share a common vertex
        # Collect all vertices from love edges
        all_love_vertices = set()
        for u, v in love_constraints:
            all_love_vertices.add(u)
            all_love_vertices.add(v)

        if len(all_love_vertices) > 2:
            # Love edges don't all share common vertex - no star configuration possible
            return f"{count}\n"

        if len(all_love_vertices) == 1:
            # All love edges are the same edge
            common_center = next(iter(all_love_vertices))
        else:
            # Two vertices with love edges between them
            candidates = list(all_love_vertices)
            candidates.sort()
            common_center = candidates[0] if constraints[0][0] == candidates[0] or constraints[0][1] == candidates[0] else candidates[1]

    # Find all vertices that appear in love constraints
    vertices_in_love = set()
    for u, v, ci in constraints:
        if ci == 1:
            vertices_in_love.add(u)
            vertices_in_love.add(v)

    if vertices_in_love:
        # The common center must be from vertices_in_love
        # Check all possible centers
        for center in vertices_in_love:
            valid_center = True

            for u, v, ci in constraints:
                if ci == 1:  # Love edge
                    if u != center and v != center:
                        valid_center = False
                        break
                elif ci == 0:  # Hate edge
                    if u == center or v == center:
                        valid_center = False
                        break

            if valid_center:
                count = (count + 1) % MOD
    else:
        # No constraints of type ci=1
        # All vertices can be potential centers
        for center in range(1, n + 1):
            valid_center = True
            for u, v, ci in constraints:
                if ci == 0:  # Hate edge
                    if u == center or v == center:
                        valid_center = False
                        break

            if valid_center:
                count = (count + 1) % MOD

    return f"{count}\n"


