import math

def get_divisors(n):
    """Get all divisors of n greater than 1"""
    divisors = []
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            if i * i != n:
                divisors.append(n // i)
    if n > 1:
        divisors.append(n)
    return sorted(divisors)

