        # Phase 0: (x, y) at time t
        # Phase 1: (x + d, y - d) at time t + 1
        # Phase 2: (x + d, y) at time t + 2
        # Phase 3: (x, y + d) at time t + 3
        positions = [
            (x, y, t),
            (x + d, y - d, t + 1),
            (x + d, y, t + 2),
            (x, y + d, t + 3),
        ]

        for px, py, pt in positions:
            # Only include valid positions within bounds
            if 0 <= px < N and 0 <= py < M:
                transformer_positions.append((px, py, pt, e))

    # Precompute total cost for each cell at each time (by summing all transformers present)
    cell_costs = [[0] * M for _ in range(N)]
    for x, y, time, cost in transformer_positions:
        cell_costs[x][y] += cost

    # dp[x][y] = minimum cost to reach (x, y)
    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = 0

    # Process cells in order of their time (x + y)
    for time in range(N + M - 1):
        for x in range(N):
            for y in range(M):
                if x + y != time:
                    continue
                if dp[x][y] == float('inf'):
