                # Move right
                if y + 1 < M:
                    dp[x][y + 1] = min(dp[x][y + 1], current_total)

                # Move down
                if x + 1 < N:
                    dp[x + 1][y] = min(dp[x + 1][y], current_total)

    return str(dp[N - 1][M - 1])

