    if not asterisks:
        return '0 0'

    if not packmen:
        return f"{len(asterisks)} 0"

    # Greedy approach: For each asterisk, assign it to the nearest packman
    # This maximizes the number of asterisks eaten while minimizing time
    count = 0
    max_time = 0
    visited_asterisk = [False] * len(asterisks)

    # For each packman, try to assign asterisks (greedy selection)
    for packman_idx, p in enumerate(packmen):
        # Try left direction first (packman at p can eat asterisks at positions < p)
        left_range = []
        for a_idx, pos_a in enumerate(asterisks):
            if pos_a < p and not visited_asterisk[a_idx]:
                left_range.append((p - pos_a, a_idx))

        # Try right direction (packman at p can eat asterisks at positions > p)
        right_range = []
        for a_idx, pos_a in enumerate(asterisks):
            if pos_a > p and not visited_asterisk[a_idx]:
                right_range.append((pos_a - p, a_idx))

        # Choose direction that gives better assignments (prefer shorter distances)
        available = left_range + right_range

        if not available:
            continue

        # Sort by distance and assign to closest unvisited asterisks
        available.sort()
        for dist, a_idx in available[:]:
            visited_asterisk[a_idx] = True
            count += 1
            max_time = max(max_time, dist)
            # Remove from available to avoid multiple assignments
            if not available:
                break
        else:
            # Rebuild available with visited check
            left_range = [(p - pos_a, a_idx) for a_idx, pos_a in enumerate(asterisks) 
                         if pos_a < p and not visited_asterisk[a_idx]]
            right_range = [(pos_a - p, a_idx) for a_idx, pos_a in enumerate(asterisks) 
                          if pos_a > p and not visited_asterisk[a_idx]]
            for dist, a_idx in sorted(left_range + right_range):
                visited_asterisk[a_idx] = True

