                return tree[u]['value']

            left_val = compute(tree[u]['left'])
            right_val = compute(tree[u]['right'])

            # For complete binary trees, use tree depth
            depth = 0
            def get_depth(v):
                nonlocal depth
                if tree[v]['type'] == 'leaf':
                    return 0
                depth += 1
                return max(get_depth(tree[v]['left']), get_depth(tree[v]['right']))

