def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return '0\n'

    n, m = map(int, lines[0].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    # Detect bridges using Tarjan's algorithm / DFS
    time_counter = [0]
    tin = [0] * (n + 1)
    low = [0] * (n + 1)
    parent = [0] * (n + 1)
    bridges = []

    def dfs_bridge(u):
        visited = [u]
        time_counter[0] += 1
        tin[u] = low[u] = time_counter[0]

        for v in adj[u]:
            if not visited[u]:
                continue
            if v == parent[u]:
                continue
            if tin[v] != 0 and tin[v] < tin[u]:
                continue

            if tin[v] == 0:
                parent[v] = u
                dfs_bridge(v)
                low[u] = min(low[u], low[v])
                if low[v] > tin[u]:
                    bridges.append((u, v))
            else:
                low[u] = min(low[u], tin[v])

    # Run DFS from node 1 (graph is connected)
    dfs_bridge(1)

    if bridges:
        return '0\n'

    # Find strong orientation
    # In a 2-edge-connected graph, we can use DFS traversal order
    # Orient tree edges parent->child, back edges child->parent

    time_counter = [0]
    tin = [0] * (n + 1)
    orientation = {}

    def dfs_orient(u):
        time_counter[0] += 1
        tin[u] = time_counter[0]

        for v in adj[u]:
            if tin[v] == 0:
                orientation[(u, v)] = True
                dfs_orient(v)
            elif tin[v] < tin[u]:
                # Back edge - direct from v to u (v is ancestor)
                orientation[(v, u)] = True

    dfs_orient(1)

    # Output orientation for all edges
    output_lines = []
    for u, v in edges:
        if orientation.get((u, v), False):
            output_lines.append(f"{u} {v}")
        elif orientation.get((v, u), False):
            output_lines.append(f"{v} {u}")
        else:
            # Should not happen in a connected graph with proper orientation
            if tin[v] > tin[u]:
                output_lines.append(f"{u} {v}")
            else:
                output_lines.append(f"{v} {u}")

    return '\n'.join(output_lines) + '\n'


