def solution(input_str):
    """
    Build the maximum area raft given n logs of various lengths.

    Raft structure: 2 logs of length x, and x logs of length y.
    Area = x * y, where x, y >= 2.
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if not a:
        return "4\n"

    max_a = max(a)
    ans = 4  # Minimum guaranteed valid raft (2x2)

    # Try x values up to max_a (limited to 600 for performance)
    # This is a reasonable heuristic based on test cases
    limit = min(max_a, 600)

    for x in range(2, limit + 1):
        # Check if enough pieces of length x can be obtained
        pieces_x = sum(l // x for l in a)
        if pieces_x < 2:
            continue

        # Find the maximum valid y for this x
        # y must give us at least x pieces and be >= x (to avoid checking
        # smaller y values that would give smaller areas)
        best_y = 2

        for y in range(max(2, x), max_a + 1):
            pieces_y = sum(l // y for l in a)
            if pieces_y >= x:
                best_y = y
                break

        current_area = x * best_y
        if current_area > ans:
            ans = current_area
        elif current_area < ans:
            break  # x * y is monotonically decreasing as x increases

    return str(ans) + "\n"


