        col_inv = False

        # Check if we need to apply inversions after shifts
        # We can't simply apply operations out of order, so we need to handle transitions
        # between shift ops and inversion ops

        # Process operations
        for op_char in ops:
            if op_char == 'I':
                # Invert all rows
                for i in range(n):
                    # Create inverse permutation
                    inv = [0] * (n + 1)
                    for col in range(n):
                        inv[rows[i][col]] = col + 1  # value -> position (1-indexed)
                    new_row = [0] * n
                    for val in range(1, n + 1):
                        col = inv[val] - 1
                        new_row[col] = val
                    rows[i] = new_row

            elif op_char == 'C':
                # Invert all columns
                for j in range(n):
                    # Extract column
                    col = [rows[i][j] for i in range(n)]
                    # Build inverse
                    inv = [0] * (n + 1)
                    for row_idx, val in enumerate(col):
                        inv[val] = row_idx + 1  # value -> position
                    # Reconstruct
                    new_col = [0] * n
                    for val in range(1, n + 1):
                        row_idx = inv[val] - 1
                        new_col[row_idx] = val
                    # Apply back
                    for i in range(n):
                        rows[i][j] = new_col[i]

            elif op_char == 'R':
                # Shift columns right
                # Each column element moves to (j+1) mod n
                for i in range(n):
                    new_row = [0] * n
                    for j in range(n):
                        new_row[j] = rows[i][(j - 1) % n]
                    rows[i] = new_row

            elif op_char == 'L':
                # Shift columns left
                for i in range(n):
                    new_row = [0] * n
                    for j in range(n):
                        new_row[j] = rows[i][(j + 1) % n]
                    rows[i] = new_row

            elif op_char == 'D':
                # Shift rows down
                for j in range(n):
                    new_col = [0] * n
                    for i in range(n):
                        new_col[i] = rows[(i - 1) % n][j]
                    for i in range(n):
                        rows[i][j] = new_col[i]

            elif op_char == 'U':
                # Shift rows up
                for j in range(n):
                    new_col = [0] * n
                    for i in range(n):
                        new_col[i] = rows[(i + 1) % n][j]
                    for i in range(n):
                        rows[i][j] = new_col[i]

        return rows

