    if not lines:
        return "-1\n"

    parts = lines[0].split()
    if len(parts) < 3:
        return "-1\n"

    try:
        maxx = int(parts[0])
        maxy = int(parts[1])
        w = int(parts[2])
    except (ValueError, IndexError):
        return "-1\n"

    best_x, best_y = -1, -1
    min_prod = float('inf')

    # Precompute reversals for efficiency
    max_val = max(maxx, maxy)
    reversals = {}
    for i in range(1, max_val + 1):
        reversals[i] = rev(i)

    # Iterate through possible x and y values
    for x in range(1, maxx + 1):
        # Early termination if x alone exceeds current best product
        if x >= min_prod:
            break

        for y in range(1, maxy + 1):
            prod = x * y
            if prod >= min_prod:
                break

            # Count lucky tickets
            lucky = 0
            for a in range(1, x + 1):
                ra = reversals[a]
                for b in range(1, y + 1):
                    if ra * b == reversals[b] * a:
                        lucky += 1

                # Early exit if we've found enough lucky tickets
                if lucky >= w:
                    break

            # If valid, update best solution
            if lucky >= w and prod < min_prod:
                min_prod = prod
                best_x, best_y = x, y

    if best_x != -1:
        return f"{best_x} {best_y}\n"
    return "-1\n"

